"""Tests for TimesFMForecaster.

TimesFmForecaster has a very restrictive dependency set,
which may cancel out with the matrix testing strategy.

Therefore, we call a check_estimator separately.
"""

# copyright: sktime developers, BSD-3-Clause License (see LICENSE file)

import numpy as np
import pytest

from sktime.datasets import load_airline
from sktime.forecasting.timesfm import TimesFMForecaster
from sktime.tests.test_switch import run_test_for_class
from sktime.utils import check_estimator

# Reference forecasts were generated by calling the upstream ``timesfm`` package
# directly, without sktime, on CPU (timesfm 1.1.0, the source of the vendored
# ``sktime.libs.timesfm``, with jax/jaxlib 0.4.26, paxml/praxis 1.4.0, numpy 1.26.4,
# Python 3.10), from checkpoint google/timesfm-1.0-200m at revision
# 8775f7531211ac864b739fe776b0b255c277e2be. The full generator, which inlines the
# airline values instead of importing sktime, is in the PR description (#11326):
#
#   import os
#   import numpy as np
#   import timesfm
#   from huggingface_hub import snapshot_download
#
#   y = np.asarray(AIRLINE_VALUES, dtype=np.float64)[:-12]  # load_airline values
#   ckpt = snapshot_download(
#       "google/timesfm-1.0-200m", revision="8775f7531211ac864b739fe776b0b255c277e2be"
#   )
#   tfm = timesfm.TimesFm(
#       context_len=160,  # TimesFMForecaster default: next multiple of 32 above 132
#       horizon_len=150,  # max(128, max(fh))
#       input_patch_len=32,
#       output_patch_len=128,
#       num_layers=20,
#       model_dims=1280,
#       per_core_batch_size=32,
#       backend="cpu",
#   )
#   tfm.load_from_checkpoint(checkpoint_path=os.path.join(ckpt, "checkpoints"))
#   point_forecast, _ = tfm.forecast(np.expand_dims(y, axis=0), freq=[0])
#   point_forecast[0, [0, 1, 2, 128, 149]]
#
# The other cases change ``freq`` and the training length, mirroring
# TimesFMForecaster: ``horizon_len`` is ``max(horizon_len, max(fh))`` and the
# forecast is indexed at ``fh - 1``. All cases resolve to context_len=160 and
# horizon_len=150, so the checkpoint is loaded once, as the model cache keys on both.
#
# The steps are sparse and go past output_patch_len=128, so the steps after 128
# come from a second autoregressive decode step.
_TIMESFM_FH = [1, 2, 3, 129, 150]

# Each case is (n_train, forecaster params, expected values at _TIMESFM_FH).
_TIMESFM_REFERENCE_CASES = {
    # all defaults: 132 points front-padded to context_len=160
    "default": (
        132,
        {},
        [
            401.7046813964844,
            392.53509521484375,
            429.7331848144531,
            602.2587280273438,
            635.2188720703125,
        ],
    ),
    # medium frequency, passed to the model as its frequency input
    "freq1": (
        132,
        {"freq": 1},
        [
            401.327880859375,
            386.6180114746094,
            420.43597412109375,
            634.5017700195312,
            706.54150390625,
        ],
    ),
    # 20 points, front-padded by more than four input patches
    "short-history": (
        20,
        {"context_len": 160},
        [
            152.55755615234375,
            141.4217071533203,
            131.2585906982422,
            129.93707275390625,
            127.61333465576172,
        ],
    ),
}


@pytest.mark.skipif(
    not run_test_for_class(TimesFMForecaster),
    reason="run test only if softdeps are present and incrementally (if requested)",
)
def test_timesfmforecaster():
    """Run standard test suite for TimesFMForecaster.

    TimesFmForecaster has a very restrictive dependency set,
    which may cancel out with the matrix testing strategy.

    Therefore, we call a check_estimator separately.
    """
    check_estimator(TimesFMForecaster, raise_exceptions=True)


@pytest.mark.skipif(
    not run_test_for_class(TimesFMForecaster),
    reason="run test only if softdeps are present and incrementally (if requested)",
)
def test_timesfm_airline_predictions_match_upstream_reference():
    """TimesFMForecaster predictions match the upstream ``timesfm`` implementation.

    The cases run in one test rather than as parametrized tests, since loading the
    200M checkpoint peaks at about 12 GB of memory, and several loads in parallel
    under ``pytest -n auto`` would exceed the memory of a CI runner.
    """
    y = load_airline()
    fh = _TIMESFM_FH

    for case, (n_train, params, expected) in _TIMESFM_REFERENCE_CASES.items():
        y_pred = TimesFMForecaster(**params).fit(y.iloc[:n_train], fh=fh).predict()

        np.testing.assert_allclose(
            y_pred.to_numpy(),
            np.asarray(expected),
            rtol=1e-5,
            atol=1e-4,
            err_msg=f"case: {case}",
        )


@pytest.mark.skipif(
    not run_test_for_class(TimesFMForecaster),
    reason="run test only if softdeps are present and incrementally (if requested)",
)
def test_timesfm_single_step_fh_without_horizon_len():
    """horizon_len=None takes the horizon from an fh with a single step."""
    y = load_airline().iloc[:-12]
    forecaster = TimesFMForecaster(
        horizon_len=None,
        repo_id=None,
        output_patch_len=32,
        num_layers=1,
        model_dims=16,
        per_core_batch_size=1,
    )

    y_pred = forecaster.fit(y, fh=[3]).predict()

    assert forecaster._horizon_len == 3
    assert len(y_pred) == 1
    assert y_pred.index[0] == y.index[-1] + 3
